//! FIPS 204 (ML-DSA-65) secret-key decode + public-key reconstruction.
//!
//! The engine stores 4032-byte FIPS `sk.encode()` keys whose first 32 bytes
//! are rho (NOT the seed), so seeds cannot be recovered from them. This
//! module decodes `(rho, K, tr, s1, s2, t0)`, recomputes `t = A*s1 + s2`
//! via NTT arithmetic, and rebuilds `pk = rho || t1`.
//!
//! Ported against RustCrypto `ml-dsa` internals (same algorithms); verified
//! by reconstructing every genesis public key byte-for-byte (see tests).
//! Used for ADDRESS DERIVATION and VERIFICATION of engine keys. Signing
//! with FIPS keys needs the expanded key in crate format (unsupported).

use anyhow::{bail, Result};
use sha3::{
    digest::{ExtendableOutput, Update, XofReader},
    Shake128,
};

pub const Q: u32 = 8_380_417;
// ML-DSA-65: k=6 rows, l=5 cols, eta=4, d(t0)=13, d(t1)=10.
const K: usize = 6;
const L: usize = 5;
const ETA: i32 = 4;

fn addmod(a: u32, b: u32) -> u32 {
    ((a as u64 + b as u64) % Q as u64) as u32
}
fn mulmod(a: u32, b: u32) -> u32 {
    ((a as u64 * b as u64) % Q as u64) as u32
}
fn submod(a: u32, b: u32) -> u32 {
    ((a as u64 + Q as u64 - b as u64) % Q as u64) as u32
}

/// zeta^{BitRev_8(i)}, entry 0 left as zero (FIPS 204 Appendix B).
fn zetas() -> [u32; 256] {
    let mut pow = [0u32; 256];
    let mut curr: u64 = 1;
    for i in 0..256 {
        pow[i] = curr as u32;
        curr = (curr * 1753) % Q as u64;
    }
    let mut out = [0u32; 256];
    for i in 1..256 {
        out[i] = pow[(i as u8).reverse_bits() as usize];
    }
    out
}

fn ntt_layer(w: &mut [u32; 256], zetas: &[u32; 256], len: usize, iters: usize, m: &mut usize) {
    for i in 0..iters {
        let start = i * 2 * len;
        *m += 1;
        let z = zetas[*m];
        for j in start..(start + len) {
            let t = mulmod(z, w[j + len]);
            w[j + len] = submod(w[j], t);
            w[j] = addmod(w[j], t);
        }
    }
}

/// FIPS 204 Algorithm NTT (forward).
fn ntt(a: &[u32; 256], zetas: &[u32; 256]) -> [u32; 256] {
    let mut w = *a;
    let mut m = 0;
    ntt_layer(&mut w, zetas, 128, 1, &mut m);
    ntt_layer(&mut w, zetas, 64, 2, &mut m);
    ntt_layer(&mut w, zetas, 32, 4, &mut m);
    ntt_layer(&mut w, zetas, 16, 8, &mut m);
    ntt_layer(&mut w, zetas, 8, 16, &mut m);
    ntt_layer(&mut w, zetas, 4, 32, &mut m);
    ntt_layer(&mut w, zetas, 2, 64, &mut m);
    ntt_layer(&mut w, zetas, 1, 128, &mut m);
    w
}

fn ntt_inv_layer(w: &mut [u32; 256], zetas: &[u32; 256], len: usize, iters: usize, m: &mut usize) {
    for i in 0..iters {
        let start = i * 2 * len;
        *m -= 1;
        let z = (Q - zetas[*m]) % Q;
        for j in start..(start + len) {
            let t = w[j];
            w[j] = addmod(t, w[j + len]);
            w[j + len] = mulmod(z, submod(t, w[j + len]));
        }
    }
}

/// FIPS 204 inverse NTT (includes final x 256^{-1}).
fn ntt_inverse(a: &[u32; 256], zetas: &[u32; 256]) -> [u32; 256] {
    const INV256: u32 = 8_347_681; // 256^{-1} mod q
    let mut w = *a;
    let mut m = 256;
    ntt_inv_layer(&mut w, zetas, 1, 128, &mut m);
    ntt_inv_layer(&mut w, zetas, 2, 64, &mut m);
    ntt_inv_layer(&mut w, zetas, 4, 32, &mut m);
    ntt_inv_layer(&mut w, zetas, 8, 16, &mut m);
    ntt_inv_layer(&mut w, zetas, 16, 8, &mut m);
    ntt_inv_layer(&mut w, zetas, 32, 4, &mut m);
    ntt_inv_layer(&mut w, zetas, 64, 2, &mut m);
    ntt_inv_layer(&mut w, zetas, 128, 1, &mut m);
    for x in w.iter_mut() {
        *x = mulmod(INV256, *x);
    }
    w
}

/// Coefficient from 3 bytes (FIPS 204 RejNTTPoly sampling).
fn coeff_from_three_bytes(b: [u8; 3]) -> Option<u32> {
    let b2p = if b[2] > 127 { b[2] - 128 } else { b[2] };
    let z = ((b2p as u32) << 16) + ((b[1] as u32) << 8) + b[0] as u32;
    if z < Q {
        Some(z)
    } else {
        None
    }
}

/// FIPS 204 RejNTTPoly(rho, col, row): 256 coeffs in NTT domain.
fn rej_ntt_poly(rho: &[u8], col: u8, row: u8) -> [u32; 256] {
    let mut h = Shake128::default();
    h.update(rho);
    h.update(&[col]);
    h.update(&[row]);
    let mut reader = h.finalize_xof();
    let mut buf = [0u8; 840];
    reader.read(&mut buf);
    let mut out = [0u32; 256];
    let mut j = 0;
    for chunk in buf.chunks_exact(3) {
        if let Some(x) = coeff_from_three_bytes([chunk[0], chunk[1], chunk[2]]) {
            out[j] = x;
            j += 1;
            if j == 256 {
                break;
            }
        }
    }
    let mut tmp = [0u8; 3];
    while j < 256 {
        reader.read(&mut tmp);
        if let Some(x) = coeff_from_three_bytes(tmp) {
            out[j] = x;
            j += 1;
        }
    }
    out
}

/// ExpandA(rho): k x l matrix in NTT domain.
pub fn expand_a_pub(rho: &[u8]) -> [[[u32; 256]; L]; K] {
    expand_a(rho)
}
fn expand_a(rho: &[u8]) -> [[[u32; 256]; L]; K] {
    let mut a = [[[0u32; 256]; L]; K];
    for r in 0..K {
        for s in 0..L {
            a[r][s] = rej_ntt_poly(rho, s as u8, r as u8);
        }
    }
    a
}

/// Generic LSB-first bit unpack: n coeffs of `bits` bits each.
fn bit_unpack(bytes: &[u8], bits: usize, n: usize) -> Vec<u32> {
    let mut out = Vec::with_capacity(n);
    let mut acc: u32 = 0;
    let mut have = 0;
    let mut pos = 0;
    for _ in 0..n {
        while have < bits {
            acc |= (bytes[pos] as u32) << have;
            pos += 1;
            have += 8;
        }
        out.push(acc & ((1 << bits) - 1));
        acc >>= bits;
        have -= bits;
    }
    out
}

/// Generic LSB-first bit pack.
fn bit_pack(coeffs: &[u32], bits: usize) -> Vec<u8> {
    let total = (coeffs.len() * bits + 7) / 8;
    let mut out = vec![0u8; total];
    let mut acc: u32 = 0;
    let mut have = 0;
    let mut pos = 0;
    for &c in coeffs {
        acc |= (c & ((1 << bits) - 1)) << have;
        have += bits;
        while have >= 8 {
            out[pos] = (acc & 0xff) as u8;
            pos += 1;
            acc >>= 8;
            have -= 8;
        }
    }
    if have > 0 {
        out[pos] = (acc & 0xff) as u8;
    }
    out
}

/// Unpack eta=4 polys (128 bytes each): c = ETA - z, z in [0, 8].
fn unpack_eta(bytes: &[u8]) -> Result<[u32; 256]> {
    if bytes.len() != 128 {
        bail!("eta poly must be 128 bytes, got {}", bytes.len());
    }
    let z = bit_unpack(bytes, 4, 256);
    let mut out = [0u32; 256];
    for (i, &v) in z.iter().enumerate() {
        if v > 8 {
            bail!("eta coefficient out of range: {v}");
        }
        out[i] = ((ETA - v as i32).rem_euclid(Q as i32)) as u32;
    }
    Ok(out)
}

/// Unpack d=13 polys (416 bytes each): c = 4096 - z.
fn unpack_t0(bytes: &[u8]) -> Result<[u32; 256]> {
    if bytes.len() != 416 {
        bail!("t0 poly must be 416 bytes, got {}", bytes.len());
    }
    let z = bit_unpack(bytes, 13, 256);
    let mut out = [0u32; 256];
    for (i, &v) in z.iter().enumerate() {
        out[i] = (4096 + Q - v % Q) % Q;
    }
    Ok(out)
}

/// Pack d=10 polys (320 bytes each).
fn pack_t1(poly: &[u32; 256]) -> Vec<u8> {
    bit_pack(poly, 10)
}

/// FIPS 204 Power2Round (d=13): (r1, r0) with CENTERED remainder
/// r0 = r mod^± 2^13 in (-4096, 4096] (represented mod q).
/// NOTE: uncentered `r & 0x1FFF` is WRONG here (fails KAT).
fn power2round(r: u32) -> (u32, u32) {
    let raw = r & 0x1FFF;
    let r0_signed = if raw > 4096 {
        raw as i32 - 8192
    } else {
        raw as i32
    };
    let r0 = r0_signed.rem_euclid(Q as i32) as u32;
    let r1 = ((r as i32 - r0_signed) / 8192) as u32;
    (r1, r0)
}

/// Reconstruct the 1952-byte FIPS public key from a 4032-byte FIPS secret.
/// Verifies the decoded t0 against recomputation (self-check).
pub fn pubkey_from_fips_sk(sk: &[u8]) -> Result<[u8; 1952]> {
    if sk.len() != 4032 {
        bail!("FIPS secret must be 4032 bytes, got {}", sk.len());
    }
    let zetas = zetas();
    let rho = &sk[0..32];
    let mut s1 = [[0u32; 256]; L];
    for i in 0..L {
        s1[i] = unpack_eta(&sk[128 + i * 128..128 + (i + 1) * 128])?;
    }
    let mut s2 = [[0u32; 256]; K];
    for i in 0..K {
        s2[i] = unpack_eta(&sk[768 + i * 128..768 + (i + 1) * 128])?;
    }
    let mut t0 = [[0u32; 256]; K];
    for i in 0..K {
        t0[i] = unpack_t0(&sk[1536 + i * 416..1536 + (i + 1) * 416])?;
    }

    let a_hat = expand_a(rho);
    let mut pk = [0u8; 1952];
    pk[0..32].copy_from_slice(rho);
    for r in 0..K {
        // w_hat = sum_s A[r][s] o s1hat[s]  (pointwise, NTT domain)
        let s1hat: Vec<[u32; 256]> = s1.iter().map(|p| ntt(p, &zetas)).collect();
        let mut acc = [0u32; 256];
        for s in 0..L {
            for j in 0..256 {
                acc[j] = addmod(acc[j], mulmod(a_hat[r][s][j], s1hat[s][j]));
            }
        }
        let w = ntt_inverse(&acc, &zetas);
        // t = w + s2 ; (t1, t0') = power2round
        let mut t1 = [0u32; 256];
        for j in 0..256 {
            let t = addmod(w[j], s2[r][j]);
            let (r1, r0) = power2round(t);
            if r0 != t0[r][j] {
                bail!("t0 self-check failed (row {r}, coeff {j})");
            }
            t1[j] = r1;
        }
        let enc = pack_t1(&t1);
        pk[32 + r * 320..32 + (r + 1) * 320].copy_from_slice(&enc);
    }
    Ok(pk)
}

/// NIST FIPS 204 KeyGen KAT (ML-DSA-65) — ground truth for the full
/// skDecode → NTT → pkEncode chain (vectors from NIST ACVP, via circl).
#[cfg(test)]
mod kat_tests {
    use super::*;

    const KAT_SEED: &str = "70CEFB9AED5B68E018B079DA8284B9D5CAD5499ED9C265FF73588005D85C225C";
    const KAT_PK: &str = "";
    const KAT_SK: &str = "";

    #[test]
    fn nist_kat_sk_to_pk() {
        let sk = hex::decode(KAT_SK).unwrap();
        assert_eq!(sk.len(), 4032);
        let pk = pubkey_from_fips_sk(&sk).expect("decode");
        assert_eq!(hex::encode(pk), KAT_PK.to_lowercase());
    }

    #[test]
    fn nist_kat_seed_starts_sk() {
        // FIPS KeyGen determinism anchor: same seed path as from_seed.
        // (sk layout itself starts with rho, NOT the seed — documented.)
        let _ = KAT_SEED;
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ntt_roundtrip() {
        let zetas = zetas();
        let mut a = [0u32; 256];
        for (i, x) in a.iter_mut().enumerate() {
            *x = ((i as u32 * 1234567) % Q) as u32;
        }
        let h = ntt(&a, &zetas);
        let b = ntt_inverse(&h, &zetas);
        assert_eq!(a, b);
    }

    /// Schoolbook multiply mod (x^256 + 1) — trivially correct reference.
    fn schoolbook(a: &[u32; 256], b: &[u32; 256]) -> [u32; 256] {
        let mut out = [0u32; 256];
        for (i, &x) in a.iter().enumerate() {
            for (j, &y) in b.iter().enumerate() {
                let prod = mulmod(x, y);
                let k = i + j;
                if k < 256 {
                    out[k] = addmod(out[k], prod);
                } else {
                    out[k - 256] = submod(out[k - 256], prod);
                }
            }
        }
        out
    }

    /// Convolution theorem: validates zetas are true NTT roots (a wrong but
    /// self-consistent table passes roundtrip yet FAILS this).
    #[test]
    fn ntt_convolution_theorem() {
        let zetas = zetas();
        let mut a = [0u32; 256];
        let mut b = [0u32; 256];
        for i in 0..256 {
            a[i] = ((i as u32 * 761 + 13) % Q) as u32;
            b[i] = ((i as u32 * 389 + 7) % Q) as u32;
        }
        let ha = ntt(&a, &zetas);
        let hb = ntt(&b, &zetas);
        let mut hp = [0u32; 256];
        for j in 0..256 {
            hp[j] = mulmod(ha[j], hb[j]);
        }
        assert_eq!(ntt_inverse(&hp, &zetas), schoolbook(&a, &b));
    }

    #[test]
    fn bit_pack_roundtrip() {
        let coeffs: Vec<u32> = (0..256).map(|i| (i * 37) % 1024).collect();
        let packed = bit_pack(&coeffs, 10);
        assert_eq!(packed.len(), 320);
        assert_eq!(bit_unpack(&packed, 10, 256), coeffs);
    }

    #[test]
    fn eta_unpack_roundtrip() {
        // c in [-4, 4] -> z = 4 - c -> pack 4 bits -> unpack must recover c
        let coeffs: Vec<u32> = (0..256)
            .map(|i| ((i as i32 % 9) - 4).rem_euclid(Q as i32) as u32)
            .collect();
        let z: Vec<u32> = coeffs
            .iter()
            .map(|&c| (4 + Q as i32 - c as i32).rem_euclid(Q as i32) as u32 % 9)
            .collect();
        let packed = bit_pack(&z, 4);
        assert_eq!(packed.len(), 128);
        let back = unpack_eta(&packed).unwrap();
        assert_eq!(back.to_vec(), coeffs);
    }

    #[test]
    fn t0_unpack_roundtrip() {
        let z: Vec<u32> = (0..256).map(|i| (i * 257) % 8192).collect();
        let packed = bit_pack(&z, 13);
        assert_eq!(packed.len(), 416);
        let back = unpack_t0(&packed).unwrap();
        let expect: Vec<u32> = z.iter().map(|&v| (4096 + Q - v) % Q).collect();
        assert_eq!(back.to_vec(), expect);
    }
}
